<?php
declare(strict_types=1);
require_once __DIR__ . '/../middleware/role-check.php';
require_once __DIR__ . '/../config/database.php';
require_once __DIR__ . '/../helpers/notify.php';
header('Content-Type: application/json; charset=utf-8');requireMarketplaceRole();
if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);echo json_encode(['success'=>false,'message'=>'Method not allowed.']);exit;}
$data=json_decode((string)file_get_contents('php://input'),true);$uid=(int)getAuthenticatedUserId();$role=(string)getAuthenticatedRole();$iid=is_array($data)?filter_var($data['inventory_id']??null,FILTER_VALIDATE_INT):false;$price=is_array($data)?filter_var($data['asking_price']??null,FILTER_VALIDATE_FLOAT):false;$condition=(string)($data['condition']??'');$description=trim((string)($data['condition_description']??''));$defects=trim((string)($data['defects']??''));$reported=filter_var($data['reported_ownership_months']??null,FILTER_VALIDATE_INT);
if(!$iid||$iid<1||$price===false||$price<=0||$price>9999999.99||!in_array($condition,['like_new','good','fair','poor'],true)||$description===''||mb_strlen($description)>1000||mb_strlen($defects)>1000||($reported!==false&&($reported<0||$reported>1200))){http_response_code(422);echo json_encode(['success'=>false,'message'=>'Enter an owned item, valid price, condition, and condition description.']);exit;}
try{$pdo->beginTransaction();$s=$pdo->prepare("SELECT i.id,i.quantity,i.status,i.assigned_at,e.name FROM inventory i JOIN equipment e ON e.id=i.equipment_id WHERE i.id=:id AND i.user_id=:user AND (e.access_role='common' OR e.access_role=:role) FOR UPDATE");$s->execute([':id'=>$iid,':user'=>$uid,':role'=>$role]);$item=$s->fetch(PDO::FETCH_ASSOC);if(!$item||$item['status']!=='assigned'||(int)$item['quantity']!==1)throw new DomainException('Only a single owned, assigned item eligible for your account can be listed.');$ins=$pdo->prepare('INSERT INTO resale_listings (inventory_id,seller_id,asking_price,condition_grade,condition_description,defects,reported_ownership_months) VALUES (:inventory,:seller,:price,:condition,:description,:defects,:months)');$ins->execute([':inventory'=>$iid,':seller'=>$uid,':price'=>number_format((float)$price,2,'.',''),':condition'=>$condition,':description'=>$description,':defects'=>$defects!==''?$defects:null,':months'=>$item['assigned_at']===null&&$reported!==false?$reported:null]);$listingId=(int)$pdo->lastInsertId();$pdo->commit();$message=sprintf('Your %s resale listing #%d is live.', $item['name'], $listingId);createNotification($pdo,$uid,'Resale listing published',$message,'success');notifyAdminsOfActivity($pdo,$uid,'New resale listing',$message,'info');http_response_code(201);echo json_encode(['success'=>true,'message'=>'Your resale listing is live.','listing_id'=>$listingId]);}catch(DomainException $e){if($pdo->inTransaction())$pdo->rollBack();http_response_code(409);echo json_encode(['success'=>false,'message'=>$e->getMessage()]);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log('AETHERYX resale create: '.$e->getMessage());http_response_code(500);echo json_encode(['success'=>false,'message'=>'Unable to publish this listing. It may already be listed.']);}
